// ============================================================================
// FreeLang Snapshot 모듈 - MVCC 가시성 관리
// ============================================================================
// 목표: 트랜잭션별 가시성 스냅샷 관리 및 MVCC 기반 행 접근성 판단
// 원리:
//   1. Snapshot: 특정 시점의 모든 활성 트랜잭션 ID 저장
//   2. MVCC 가시성: created_ts <= snap_ts AND deleted_ts > snap_ts
//   3. 활성 트랜잭션 필터: 스냅샷 생성 시점에 활성이던 tx는 보이지 않음
//   4. O(1) 제거: 배열 마지막 원소로 교환 후 제거
// 구조:
//   - 상수 정의 (제한값, 에러 코드)
//   - Snapshot, SnapshotPool 구조체
//   - 전역 상태 (풀, 활성 트랜잭션 추적)
//   - 공개 API 함수 8개
//   - 내부 헬퍼 함수 3개
// ============================================================================

module snapshot {
    // === 상수 ===

    // 제한값
    const MAX_SNAPSHOTS:      i32 = 128;
    const MAX_SNAP_ACTIVE_TX: i32 = 64;
    const MAX_ACTIVE_TX:      i32 = 64;

    // 에러 코드
    const SNAP_OK:            i32 = 0;
    const SNAP_ERR_FULL:      i32 = 80;
    const SNAP_ERR_NOT_FOUND: i32 = 81;

    // === 데이터 구조체 ===

    // 스냅샷: 특정 시점의 가시성 정보
    struct Snapshot {
        snap_id:      i32;                           // 스냅샷 ID (슬롯 인덱스)
        snap_ts:      i64;                           // 논리 타임스탬프
        tx_id:        i64;                           // 스냅샷 생성 트랜잭션 ID
        active_tx_ids: [i64];                         // 스냅샷 생성 시점의 활성 tx 배열
        active_count: i32;                           // 실제 활성 tx 개수
        is_used:      bool;                          // 슬롯 사용 여부
    }

    // 스냅샷 풀
    struct SnapshotPool {
        snaps:      [Snapshot];
        snap_count: i32;
    }

    // === 전역 상태 ===

    // 스냅샷 풀 (전역 단일 인스턴스)
    let g_snapshot_pool: SnapshotPool = SnapshotPool{
        snaps:      make([Snapshot], MAX_SNAPSHOTS),
        snap_count: 0,
    };

    // 현재 활성 트랜잭션 추적
    let g_active_tx_ids:      [i64] = make([i64], MAX_ACTIVE_TX);
    let g_active_tx_snap_ts:  [i64] = make([i64], MAX_ACTIVE_TX);
    let g_active_tx_count:    i32   = 0;

    // === 공개 API ===

    // snapshot_init: 스냅샷 시스템 초기화
    func snapshot_init() -> i32 {
        g_snapshot_pool.snaps = make([Snapshot], MAX_SNAPSHOTS);
        g_snapshot_pool.snap_count = 0;

        g_active_tx_ids = make([i64], MAX_ACTIVE_TX);
        g_active_tx_snap_ts = make([i64], MAX_ACTIVE_TX);
        g_active_tx_count = 0;

        return SNAP_OK;
    }

    // snapshot_create: 새로운 스냅샷 생성
    // 반환: (snap_id, 에러코드)
    // - snap_id: 0 이상이면 성공, -1이면 실패
    func snapshot_create(tx_id: i64, snap_ts: i64) -> (i32, i32) {
        let slot, alloc_ok = sp_alloc_slot(&g_snapshot_pool);
        if !alloc_ok {
            return (-1, SNAP_ERR_FULL);
        }

        // 새 스냅샷 생성
        let snap: Snapshot;
        snap.snap_id = slot;
        snap.snap_ts = snap_ts;
        snap.tx_id = tx_id;
        snap.active_tx_ids = make([i64], MAX_SNAP_ACTIVE_TX);
        snap.active_count = 0;
        snap.is_used = true;

        // 현재 활성 트랜잭션 복사
        let i = 0;
        for i = 0; i < g_active_tx_count && i < MAX_SNAP_ACTIVE_TX; i = i + 1 {
            snap.active_tx_ids[i] = g_active_tx_ids[i];
        }
        snap.active_count = i;

        // 풀에 저장
        g_snapshot_pool.snaps[slot] = snap;
        g_snapshot_pool.snap_count = g_snapshot_pool.snap_count + 1;

        return (slot, SNAP_OK);
    }

    // snapshot_is_visible: 행이 스냅샷에서 보이는지 판단 (MVCC)
    // 파라미터:
    //   snap_id: 스냅샷 ID
    //   created_ts: 행의 생성 타임스탬프
    //   deleted_ts: 행의 삭제 타임스탬프 (-1 = 미삭제)
    //   creator_tx_id: 행을 생성한 트랜잭션 ID
    //   my_tx_id: 현재 트랜잭션 ID
    func snapshot_is_visible(snap_id: i32, created_ts: i64, deleted_ts: i64,
                             creator_tx_id: i64, my_tx_id: i64) -> bool {
        if snap_id < 0 || snap_id >= MAX_SNAPSHOTS {
            return false;
        }

        let snap = g_snapshot_pool.snaps[snap_id];
        if !snap.is_used {
            return false;
        }

        // 기본 MVCC 가시성 판정
        let visible_mvcc = created_ts <= snap.snap_ts &&
                          (deleted_ts == -1 || deleted_ts > snap.snap_ts);

        if !visible_mvcc {
            return false;
        }

        // 추가 조건: creator_tx가 스냅샷 생성 시점에 활성이었는가?
        if creator_tx_id != my_tx_id {
            let has_active = snap_has_active_tx(snap, creator_tx_id);
            if has_active {
                // creator tx가 아직 커밋되지 않았음 → 안 보임
                return false;
            }
        }

        return true;
    }

    // snapshot_destroy: 스냅샷 파괴 및 트랜잭션 등록 해제
    func snapshot_destroy(snap_id: i32, tx_id: i64) -> i32 {
        if snap_id < 0 || snap_id >= MAX_SNAPSHOTS {
            return SNAP_ERR_NOT_FOUND;
        }

        g_snapshot_pool.snaps[snap_id].is_used = false;
        g_snapshot_pool.snap_count = g_snapshot_pool.snap_count - 1;

        snapshot_unregister_tx(tx_id);

        return SNAP_OK;
    }

    // snapshot_register_tx: 활성 트랜잭션 등록
    func snapshot_register_tx(tx_id: i64, snap_ts: i64) -> i32 {
        if g_active_tx_count >= MAX_ACTIVE_TX {
            return SNAP_ERR_FULL;
        }

        g_active_tx_ids[g_active_tx_count] = tx_id;
        g_active_tx_snap_ts[g_active_tx_count] = snap_ts;
        g_active_tx_count = g_active_tx_count + 1;

        return SNAP_OK;
    }

    // snapshot_unregister_tx: 활성 트랜잭션 제거 (O(1))
    func snapshot_unregister_tx(tx_id: i64) -> i32 {
        let idx, found = active_tx_find(tx_id);
        if !found {
            return SNAP_ERR_NOT_FOUND;
        }

        // 마지막 원소를 현재 위치로 옮기기
        if idx < g_active_tx_count - 1 {
            g_active_tx_ids[idx] = g_active_tx_ids[g_active_tx_count - 1];
            g_active_tx_snap_ts[idx] = g_active_tx_snap_ts[g_active_tx_count - 1];
