    // GC 대상 결정에 사용 (이 값보다 작은 커밋은 안전하게 GC 가능)
    func snapshot_min_visible_ts() -> i64 {
        if g_active_tx_count == 0 {
            // 활성 트랜잭션 없음 → 매우 큰 값 반환
            return 9223372036854775807;  // i64 max
        }

        // 활성 트랜잭션의 최소 타임스탐프 찾기
        let min_ts = g_active_tx_snap_ts[0];
        let i = 1;
        for i = 1; i < g_active_tx_count; i = i + 1 {
            let ts = g_active_tx_snap_ts[i];
            if ts < min_ts {
                min_ts = ts;
            }
        }

        return min_ts;
    }

    // snapshot_stats: 통계 문자열 생성
    func snapshot_stats() -> string {
        let snap_info = "SnapshotPool: ";
        snap_info = snap_info + i32_to_string(g_snapshot_pool.snap_count);
        snap_info = snap_info + "/";
        snap_info = snap_info + i32_to_string(MAX_SNAPSHOTS);
        snap_info = snap_info + ", ActiveTx: ";
        snap_info = snap_info + i32_to_string(g_active_tx_count);

